#!/usr/bin/env bash
# Agent CLI Startup Script — agent-engram
#
# Sets workspace-local directories so that AI agent state (memories,
# checkpoints, database) is scoped to this workspace and git-visible.
#
# Usage: ./start.sh
#   Requires execute permission on first use: chmod +x start.sh
#
# Activate the section matching your AI CLI tool.
# To switch tools, comment out the active section and uncomment another.
#
# Generated by autoharness. Re-run install or tune to regenerate.

set -euo pipefail

# ── GitHub Copilot CLI ──────────────────────────────────────────────────────
# COPILOT_HOME redirects the Copilot CLI database and memory to a workspace-
# local directory. This keeps agent state visible in git and isolated per
# project rather than shared across all workspaces.
#
# This script does NOT install or refresh Auto-MergeInstall / Auto-Tune.
# Register those globally with `autoharness setup-copilot-cli`.
# Re-run that setup command after upgrading autoharness so updated agent and
# skill files are recopied into the standard Copilot CLI config directory.
#
# COPILOT_EXE_PATH must be an executable path only (no arguments).
# Set ai_tools.copilot_cli.exe_path in .autoharness/config.yaml if copilot
# is not on PATH, then re-run autoharness install or tune.
#
export COPILOT_HOME="${COPILOT_HOME:-./.copilot}"
# export ENGRAM_DATA_DIR="./.engram"   # Uncomment when the agent-engram capability pack is active
#
# Fail-closed Engram preflight (PA-2 launcher contract, parity with start.ps1).
# `engram preflight "$WORKSPACE" --timeout-ms <T>` replaces the legacy sync/bind
# pre-warm under ONE budget: T is the outer budget minus 3000 ms (2000 ms relay
# grace plus 1000 ms margin). The exit status is authoritative: the agent is
# launched only when the exit status is 0 AND a Succeeded verdict line is
# present with no verdict line reporting any other state. Every failure blocks
# the launch and prints the typed failing stage, stdout and stderr.
# Optional: ENGRAM_PREWARM_TIMEOUT_MS overrides the outer budget (3001..30000).
WORKSPACE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

preflight_state_re='"state"[[:space:]]*:[[:space:]]*"([^"]*)"'
preflight_stage_re='"stage"[[:space:]]*:[[:space:]]*"([^"]*)"'
preflight_child="" preflight_out_file="" preflight_err_file=""

now_ms() {
	if [[ -n "${EPOCHREALTIME:-}" ]]; then
		local t="${EPOCHREALTIME/[.,]/}"
		echo $((10#$t / 1000))
	else
		echo $((SECONDS * 1000))
	fi
}

# Stop exactly one child PID this launcher started: TERM, a bounded grace
# period, then KILL, then reap it. Descendants of the child are never signaled.
stop_owned_child() {
	local child="$1" grace=0
	kill "$child" 2>/dev/null || true
	while kill -0 "$child" 2>/dev/null && ((grace < 1000)); do
		sleep 0.1
		grace=$((grace + 100))
	done
	if kill -0 "$child" 2>/dev/null; then
		kill -9 "$child" 2>/dev/null || true
	fi
	wait "$child" 2>/dev/null || true
}

# If the launcher is interrupted mid-preflight, stop only its own child (and
# reap it before its output files are removed). Cleared before the agent starts.
preflight_cleanup() {
	if [[ -n "$preflight_child" ]] && kill -0 "$preflight_child" 2>/dev/null; then
		stop_owned_child "$preflight_child"
	fi
	[[ -z "$preflight_out_file" ]] || rm -f -- "$preflight_out_file"
	[[ -z "$preflight_err_file" ]] || rm -f -- "$preflight_err_file"
}
trap preflight_cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

run_engram_preflight() {
	local workspace="$1" budget_ms="$2"
	local timeout_ms=$((budget_ms - 3000))
	local engram_exe="" candidate
	for candidate in "$workspace/target/debug/engram" "$workspace/target/debug/engram.exe"; do
		if [[ -f "$candidate" ]]; then
			engram_exe="$candidate"
			break
		fi
	done
	if [[ -z "$engram_exe" ]]; then
		echo "Engram preflight executable not found under $workspace/target/debug (build it with 'cargo build'). Copilot was not launched." >&2
		return 1
	fi

	echo "Engram preflight — verifying workspace before Copilot startup"
	local out_file err_file
	out_file="$(mktemp)"
	preflight_out_file="$out_file"
	err_file="$(mktemp)"
	preflight_err_file="$err_file"

	# Run outside any pipeline so the exit status is read directly from $?.
	# Output goes to files, so an unowned descendant holding a pipe open can
	# never block the launcher.
	"$engram_exe" preflight "$workspace" --timeout-ms "$timeout_ms" >"$out_file" 2>"$err_file" &
	local child=$! status=0 failure=""
	preflight_child="$child"
	# Wall-clock deadline (not summed sleep ticks). Bash without EPOCHREALTIME
	# only has whole seconds, so it gets one second of slack to never kill early.
	local slack_ms=0 started_ms
	[[ -n "${EPOCHREALTIME:-}" ]] || slack_ms=1000
	started_ms="$(now_ms)"
	while kill -0 "$child" 2>/dev/null; do
		if (($(now_ms) - started_ms >= budget_ms + slack_ms)); then
			# Terminate only the child this launcher started ($child, owned by
			# PID). Descendants it spawned are not owned by the launcher and are
			# never terminated.
			stop_owned_child "$child"
			failure="engram preflight exceeded its ${budget_ms} ms budget."
			break
		fi
		sleep 0.1
	done
	wait "$child" && status=0 || status=$?
	preflight_child=""

	local stdout stderr
	stdout="$(<"$out_file")"
	stderr="$(<"$err_file")"
	rm -f -- "$out_file" "$err_file"

	local non_zero_exit=0 succeeded=0 line
	if [[ -z "$failure" && "$status" -ne 0 ]]; then
		failure="engram preflight failed with exit code ${status}."
		non_zero_exit=1
	fi
	if [[ -z "$failure" ]]; then
		# Exit 0 is necessary but not sufficient.
		while IFS= read -r line || [[ -n "$line" ]]; do
			line="${line%$'\r'}"
			if [[ "$line" =~ $preflight_state_re ]]; then
				if [[ "${BASH_REMATCH[1]}" == "Succeeded" ]]; then
					succeeded=1
				else
					failure="engram preflight reported state '${BASH_REMATCH[1]}': ${line}"
					break
				fi
			fi
		done <<<"$stdout"
		if [[ -z "$failure" && "$succeeded" -eq 0 ]]; then
			failure="engram preflight exited 0 without a Succeeded verdict line."
		fi
	fi

	[[ -n "$stdout" ]] && printf '%s\n' "$stdout"
	if [[ -n "$failure" ]]; then
		[[ -n "$stderr" ]] && printf '%s\n' "$stderr" >&2
		# The typed stage comes from the first non-Succeeded verdict line; when the
		# process exited non-zero, any line carrying a stage is accepted.
		local failed_stage=""
		while IFS= read -r line || [[ -n "$line" ]]; do
			line="${line%$'\r'}"
			[[ "$line" =~ $preflight_stage_re ]] || continue
			local line_stage="${BASH_REMATCH[1]}"
			local is_succeeded=0
			[[ "$line" =~ $preflight_state_re && "${BASH_REMATCH[1]}" == "Succeeded" ]] && is_succeeded=1
			if [[ "$is_succeeded" -eq 0 || "$non_zero_exit" -eq 1 ]] && [[ -n "$line_stage" ]]; then
				failed_stage="$line_stage"
				break
			fi
		done <<<"$stdout"
		[[ -n "$failed_stage" ]] && echo "engram preflight failed at stage ${failed_stage}."
		echo "${failure} Copilot was not launched." >&2
		return 1
	fi
	return 0
}

if [ -z "${GITHUB_TOKEN:-}" ]; then
	if command -v gh >/dev/null 2>&1; then
		GITHUB_TOKEN="$(gh auth token 2>/dev/null || true)"
	fi
fi
export GITHUB_TOKEN="${GITHUB_TOKEN:-}"
copilot_exe="${COPILOT_EXE_PATH:-${COPILOT_EXE:-copilot}}"

if command -v "$copilot_exe" >/dev/null 2>&1; then
	copilot_exe="$(command -v "$copilot_exe")"
elif [[ ! -x "$copilot_exe" ]]; then
	echo "Unable to locate Copilot CLI. Set COPILOT_EXE_PATH (or COPILOT_EXE for backward compatibility) or add 'copilot' to PATH." >&2
	exit 1
fi

# A relative executable path was resolved against the caller's directory above;
# pin it to an absolute path before changing directory.
if [[ "$copilot_exe" == */* && "$copilot_exe" != /* ]]; then
	copilot_exe="$(cd "$(dirname "$copilot_exe")" && pwd)/$(basename "$copilot_exe")"
fi

# Anchor workspace operations to the repo dir, as start.ps1 does with
# Push-Location, so the preflight verdict and the agent see the same state.
cd "$WORKSPACE"

preflight_budget_ms=15000
if [[ -n "${ENGRAM_PREWARM_TIMEOUT_MS:-}" ]]; then
	if [[ ! "$ENGRAM_PREWARM_TIMEOUT_MS" =~ ^[0-9]{1,9}$ ]] ||
		((10#$ENGRAM_PREWARM_TIMEOUT_MS <= 3000 || 10#$ENGRAM_PREWARM_TIMEOUT_MS > 30000)); then
		echo "Invalid ENGRAM_PREWARM_TIMEOUT_MS; expected 3001..30000 milliseconds." >&2
		exit 1
	fi
	preflight_budget_ms=$((10#$ENGRAM_PREWARM_TIMEOUT_MS))
fi
run_engram_preflight "$WORKSPACE" "$preflight_budget_ms" || exit 1
trap - EXIT INT TERM

exec "$copilot_exe" "$@"

# ── Claude Code ─────────────────────────────────────────────────────────────
# Uncomment to run Claude Code with workspace-local state directories.
# CLAUDE_CONFIG_DIR redirects Claude's config and history to the workspace.
# Verify that your installed version of Claude Code supports this env variable.
#
# export CLAUDE_CONFIG_DIR="./.claude"
# claude

# ── OpenAI Codex / Agents ────────────────────────────────────────────────────
# Uncomment to run Codex with a workspace-local API key file.
#
# export OPENAI_API_KEY="$(cat .openai-token)"
# codex
